body.script:
const target =
  "https://cdn.jsdelivr.net/gh/xenonsan/dogeub_static@main/index.html";

const iframe = document.getElementById("embed");

iframe.srcdoc = `










      fetch("${target}")
        .then(response => {
          if (!response.ok) {
            throw new Error("HTTP " + response.status);
          }
          return response.text();
        })
        .then(html => {
          document.open();
          document.write(html);
          document.close();
        })
        .catch(error => {
          document.body.innerText =
            "読み込みエラー: " + error.message;
        });
    <\/script>


`;
